# The eight tables of the TPC-H schema, generated by DuckDB's tpch extension
# (`dbgen()`, deterministic for a scale factor). Runs in a fresh R process
# with duckdb; the database lives in a temporary file, so DuckDB can spill to
# disk at large scale factors, and DuckDB keeps its extension in
# tidyarena's cache.
#
# The tasks built on these tables are derived from TPC-H; they are not the
# TPC-H benchmark, and their results are not comparable with published
# TPC-H results.
generate_tpch <- function(n, seed, paths, options = list()) {
  if (!requireNamespace("duckdb", quietly = TRUE)) {
    stop("Generating the TPC-H data needs duckdb: arena_install(\"dbplyr_duckdb\") installs it.")
  }
  sf <- n / 1e7
  dbdir <- tempfile(fileext = ".duckdb")
  config <- list(extension_directory = file.path(options$cache, "duckdb-extensions"))
  con <- DBI::dbConnect(duckdb::duckdb(dbdir = dbdir, config = config))
  on.exit(
    {
      DBI::dbDisconnect(con, shutdown = TRUE)
      unlink(c(dbdir, paste0(dbdir, ".wal")))
    },
    add = TRUE
  )
  # Installed and loaded explicitly: duckdb 1.5 no longer installs known
  # extensions on first use (`autoinstall_known_extensions` is off).
  DBI::dbExecute(con, "INSTALL tpch")
  DBI::dbExecute(con, "LOAD tpch")
  DBI::dbExecute(con, sprintf("CALL dbgen(sf = %s)", format(sf, scientific = FALSE)))

  fingerprint <- list()
  for (table in setdiff(names(paths), "fingerprint")) {
    cols <- DBI::dbGetQuery(
      con,
      sprintf(
        "SELECT column_name, data_type FROM information_schema.columns WHERE table_name = '%s' ORDER BY ordinal_position",
        table
      )
    )
    # Decimals as doubles and the BIGINT keys as integers, the types R uses;
    # the keys fit up to scale factor 100.
    cast <- ifelse(
      grepl("^DECIMAL", cols$data_type),
      "DOUBLE",
      ifelse(cols$data_type == "BIGINT", "INTEGER", NA)
    )
    select <- ifelse(
      is.na(cast),
      cols$column_name,
      sprintf("CAST(%s AS %s) AS %s", cols$column_name, cast, cols$column_name)
    )
    DBI::dbExecute(
      con,
      sprintf(
        "COPY (SELECT %s FROM %s) TO '%s' (FORMAT parquet, COMPRESSION uncompressed)",
        paste(select, collapse = ", "),
        table,
        paths[[table]]
      )
    )
    numeric <- cols$column_name[grepl("^(DECIMAL|INTEGER|BIGINT|DOUBLE)", cols$data_type)]
    sums <- paste0(", sum(", numeric, ")::DOUBLE AS ", numeric, collapse = "")
    fingerprint[[table]] <- as.list(DBI::dbGetQuery(
      con,
      sprintf("SELECT count(*)::DOUBLE AS nrow%s FROM %s", sums, table)
    ))
  }
  fingerprint
}
